export interface Template {
  id: number;
  slug: string;
  name: string;
  category: string;
  categorySlug: string;
  description: string;
  longDescription: string;
  badge: 'gratis' | 'premium' | 'popular';
  usageCount: number;
  fields: TemplateField[];
  faq: { q: string; a: string }[];
  relatedIds: number[];
  legalInfo: string;
  keywords: string[];
}

export interface TemplateField {
  id: string;
  label: string;
  type: 'text' | 'date' | 'textarea' | 'select' | 'checkbox' | 'personnummer' | 'email' | 'phone' | 'address';
  placeholder?: string;
  required?: boolean;
  options?: string[];
  group?: 'givare' | 'havare' | 'detaljer';
  helpText?: string;
}

export interface Category {
  slug: string;
  name: string;
  icon: string;
  description: string;
  color: string;
  templateCount: number;
}

